mapper.update:
INSERT INTO J_직원_발령이력 (아이디, 발령유형, 발령일, 사유, 등록일시)
SELECT #{userId}, N'휴직', ISNULL(#{transferDate,jdbcType=DATE}, CAST(GETDATE() AS date)),
       #{reason,jdbcType=NVARCHAR}, GETDATE()
FROM J_직원 WHERE 아이디 = #{userId} AND 현재재직상태 = N'재직';

UPDATE J_직원 SET 현재재직상태 = N'휴직', 수정일 = GETDATE()
WHERE 아이디 = #{userId} AND 현재재직상태 = N'재직';

UPDATE J_직원_계정 SET 계정상태 = N'정지'
WHERE 아이디 = #{userId} AND 계정상태 = N'사용'
  AND EXISTS (SELECT 1 FROM J_직원 WHERE 아이디 = #{userId} AND 현재재직상태 = N'휴직');

INSERT INTO J_직원_발령이력 (아이디, 발령유형, 발령일, 사유, 등록일시)
SELECT #{userId}, N'복직', ISNULL(#{transferDate,jdbcType=DATE}, CAST(GETDATE() AS date)),
       #{reason,jdbcType=NVARCHAR}, GETDATE()
FROM J_직원 WHERE 아이디 = #{userId} AND 현재재직상태 = N'휴직';

UPDATE J_직원 SET 현재재직상태 = N'재직', 수정일 = GETDATE()
WHERE 아이디 = #{userId} AND 현재재직상태 = N'휴직';

UPDATE J_직원_계정 SET 계정상태 = N'사용'
WHERE 아이디 = #{userId} AND 계정상태 = N'정지'
  AND EXISTS (SELECT 1 FROM J_직원 WHERE 아이디 = #{userId} AND 현재재직상태 = N'재직');
